Definition alloc_pre_sec_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo size needed TSD CTX TH sb SO : Z) (T : list Z) (rest : list word) : machine_state -> Prop :=
  fun ms' => exists (x5 x6 x7 x14 x15 x16 x17 x28 x29 x30 x31 : word) m' (j8 : list byte),
    ms' = MS (mkR (wz 0x5035c) (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp x5 x6 x7 (wz 0) (wz size) (wz AINST) (wz (TH + 208)) (wz needed) (wz 8) x14 x15 x16 x17
                  (wz 8) (wz needed) (wz 2048) (wz size) (wz AINST) (wz SO) (Z_to_bv 64 (-8)) (wz 7) (wz TH) (wz 1) x28 x29 x30 x31)
             F (Z_to_bv 64 0x54814) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ AENV tp TSD CTX TH sb SO T rest m' /\ aframe sp ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m' j8 /\ stk bsegs m' lo (bv_unsigned sp + -128).

